func usageColorClass(used, max int) string {
	if max == 0 {
		return "has-text-primary"
	}
	percent := (used * 100) / max
	if percent >= 90 {
		return "has-text-danger"
	} else if percent >= 75 {
		return "has-text-warning"
	}
	return "has-text-success"
}

func usageProgressClass(used, max int) string {
	if max == 0 {
		return "is-primary"
	}
	percent := (used * 100) / max
	if percent >= 90 {
		return "is-danger"
	} else if percent >= 75 {
		return "is-warning"
	}
	return "is-success"
}

func usagePercent(used, max int) int {
	if max == 0 {
		return 0
	}
	return (used * 100) / max
}

