func getSettingOrDefault(settings *LimitsSettings, field string, defaultVal int) int {
	if settings == nil {
		return defaultVal
	}
	switch field {
	case "MaxVMPerUser":
		if settings.MaxVMPerUser > 0 {
			return settings.MaxVMPerUser
		}
	case "MaxSnapshots":
		if settings.MaxSnapshots > 0 {
			return settings.MaxSnapshots
		}
	}
	return defaultVal
}

func getVMSettingStr(settings *VMSettings, field string, defaultVal string) string {
	if settings == nil {
		return defaultVal
	}
	var val int
	switch field {
	case "SocketsMax":
		val = settings.SocketsMax
	case "CoresMax":
		val = settings.CoresMax
	case "RAMMin":
		val = settings.RAMMin
	case "RAMMax":
		val = settings.RAMMax
	case "DiskMin":
		val = settings.DiskMin
	case "DiskMax":
		val = settings.DiskMax
	default:
		return defaultVal
	}
	if val <= 0 {
		return defaultVal
	}
	return fmt.Sprintf("%d", val)
}

func getNodeSettingStr(settings *NodeSettings, field string, defaultVal string) string {
	if settings == nil {
		return defaultVal
	}
	var val int
	switch field {
	case "CoresMax":
		val = settings.CoresMax
	case "RAMMin":
		val = settings.RAMMin
	case "RAMMax":
		val = settings.RAMMax
	default:
		return defaultVal
	}
	if val <= 0 {
		return defaultVal
	}
	return fmt.Sprintf("%d", val)
}

